const translations=[...document.querySelectorAll('[data-pt][data-es]')];
function setLanguage(lang){lang=lang==='es'?'es':'pt';translations.forEach(el=>el.textContent=el.dataset[lang]);document.documentElement.lang=lang==='es'?'es':'pt-BR';document.querySelectorAll('[data-lang]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.lang===lang)));document.querySelectorAll('[data-contact]').forEach(a=>{const k=a.dataset.contact==='kelly';const name=k?'Kelly':'Cristian';const message=lang==='es'?`Hola, ${name}. Vi la página de Casal Conselheiro y me gustaría conversar sobre mi empresa.`:`Olá, ${name}. Conheci o Casal Conselheiro pelo site e gostaria de conversar sobre minha empresa.`;a.href=`https://wa.me/${k?'5511963680568':'5511930090061'}?text=${encodeURIComponent(message)}`;a.target='_blank';a.rel='noopener noreferrer'});document.title=lang==='es'?'Casal Conselheiro | Cristian França & Kelly França — Asesoría empresarial':'Casal Conselheiro | Cristian França & Kelly França';document.querySelector('meta[name="description"]').content=lang==='es'?'Cristian y Kelly França: más de 20 años de experiencia en gestión, personas, liderazgo y desarrollo empresarial. Conoce nuestros servicios y conversa por WhatsApp.':'Cristian e Kelly França: mais de 20 anos de experiência em gestão, pessoas, liderança e desenvolvimento empresarial. Conheça nossa atuação e converse pelo WhatsApp.';document.querySelectorAll('img[data-alt-es]').forEach(img=>img.alt=lang==='es'?img.dataset.altEs:img.dataset.altPt);try{localStorage.setItem('cc-language',lang)}catch{}}
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>setLanguage(b.dataset.lang)));let lang='pt';try{lang=localStorage.getItem('cc-language')||'pt'}catch{}setLanguage(lang);
const menuButton=document.querySelector('.menu-toggle'),navigation=document.querySelector('#navigation');
function closeMenu(){menuButton.setAttribute('aria-expanded','false');navigation.classList.remove('open')}
menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));navigation.classList.toggle('open',open)});navigation.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menuButton.getAttribute('aria-expanded')==='true'){closeMenu();menuButton.focus()}});document.addEventListener('click',e=>{if(!document.querySelector('header').contains(e.target))closeMenu()});
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
if('IntersectionObserver'in window&&!reduced){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.06});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));document.body.classList.add('motion')}
let queued=false;function updateScroll(){const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.reading-progress').style.width=(max>0?scrollY/max*100:0)+'%';document.querySelector('header').classList.toggle('scrolled',scrollY>80);document.querySelector('.mobile-contact').classList.toggle('shown',scrollY>650);queued=false}addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(updateScroll)}},{passive:true});updateScroll();addEventListener('resize',()=>{if(innerWidth>900)closeMenu()},{passive:true});
if(!reduced){document.querySelectorAll('.button').forEach(button=>button.addEventListener('pointerdown',e=>{const r=button.getBoundingClientRect(),ripple=document.createElement('i');ripple.className='ripple';ripple.style.left=(e.clientX-r.left)+'px';ripple.style.top=(e.clientY-r.top)+'px';button.append(ripple);setTimeout(()=>ripple.remove(),650)}));if(matchMedia('(hover:hover) and (pointer:fine)').matches){document.querySelectorAll('.service-card').forEach(card=>{let busy=false;card.addEventListener('pointermove',e=>{if(busy)return;busy=true;requestAnimationFrame(()=>{const r=card.getBoundingClientRect();card.style.setProperty('--x',(e.clientX-r.left)+'px');card.style.setProperty('--y',(e.clientY-r.top)+'px');busy=false})})})}}
